{
  "title": "Đà Lạt trong nhà, mưa vẫn vui",
  "summary": "Trời mưa thì mình đổi gió: một ngày loanh quanh phố, ăn ngon và ngồi quán ấm, khô ráo từ sáng tới tối.",
  "stops": [
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa đầu ngày mưa cứ là bánh căn nóng hổi, ngồi trong nhà nhìn phố ướt cũng thấy ấm."
    },
    {
      "poi_id": "p136",
      "kind": "activity",
      "must_do_id": null,
      "note": "Ga Đà Lạt có mái che, vừa ngắm kiến trúc vừa tránh mưa, hợp với người thích đi chậm."
    },
    {
      "poi_id": "p23",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bảo tàng Lâm Đồng kín gió, trưa mưa vào đây đọc lịch sử và văn hoá phố núi là vừa."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Nem nướng ngồi bàn đàng hoàng, no bụng mà không ướt giày, đúng kiểu mình thích."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mây Lang Thang có mái che, cà phê ấm cho buổi chiều mưa, ngồi lâu một chút cũng được."
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tối mưa thì vào Marché, trong nhà có đủ trò vui, khỏi lo ướt áo."
    }
  ]
}
```

